import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 fuzzAddr) public {
        // Bound depositAmount to avoid overflow in balance, keep it wide
        depositAmount = bound(depositAmount, 1, 1e36);
        // Generate an address that is not msg.sender and has no special precompile collisions
        address caller = address(uint160(uint256(keccak256(abi.encode(fuzzAddr)))));
        vm.assume(caller != address(0) && caller != address(this));

        // Fund the caller and deposit Ether into contract via fallback
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        (bool deposited,) = address(c).call{value: depositAmount}("");
        require(deposited, "deposit failed");

        // Now caller withdraws
        vm.prank(caller);
        try c.withdraw() { } catch { }

        // After withdraw, the balance of the caller must be 0 in the reference contract.
        // The mutant transferred 1 ether but zeroed the original balance, leaving a discrepancy if depositAmount != 1 ether.
        assertEq(c.balances(caller), 0);
    }
}

