pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address caller, address other) public {
        // Restrict to reasonable amount (<= type(uint256).max / 2 to avoid overflow in summation)
        vm.assume(amount > 0);
        vm.assume(amount <= type(uint256).max / 2);
        vm.assume(caller != address(0) && caller != address(c) && caller != address(this));
        vm.assume(other != address(0) && other != address(c) && other != address(this));
        vm.assume(caller != other);

        // Give caller some Ether to deposit
        vm.deal(caller, amount);
        vm.prank(caller);
        (bool success1,) = address(c).call{value: amount}("");
        require(success1, "deposit failed");

        // Give other some Ether and deposit as well (second depositor to make invariant non-trivial)
        vm.deal(other, amount);
        vm.prank(other);
        (bool success2,) = address(c).call{value: amount}("");
        require(success2, "deposit2 failed");

        // Record total balance before withdrawal
        uint256 totalBefore = c.balances(caller) + c.balances(other) + address(c).balance;
        // Invariant: totalBefore == 0 because deposits exactly match added balance + tracked amounts
        // Since fresh mapping entries start at 0: deposited amount * 2 tracked + contract balance = 2*amount,
        // so totalBefore = 2*amount + (-2*amount) = 0 holds.

        // Perform withdrawal by caller
        vm.prank(caller);
        c.withdraw();

        // Sum of all balances (the two known depositors) plus contract ETH should be zero after any withdraw.
        // The bug leaves caller's balance unchanged -> summed balances > 0.
        uint256 totalAfter = c.balances(caller) + c.balances(other) + address(c).balance;
        assertTrue(totalAfter == 0);
    }
}
// No adversarial helper needed: the invariant holds using only EOAs (fuzzed addresses) and the contract's own state.

