pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawCallCount, address caller) public {
        // Restrict deposit to a reasonable range to avoid overflow and keep domain wide
        vm.assume(depositAmount <= 1_000_000 ether);
        // Withdraw call count: 0 (no prior withdrawal) up to a reasonable upper bound
        vm.assume(withdrawCallCount <= 10);
        // Caller cannot be the zero address (to ensure a valid account)
        vm.assume(caller != address(0));
        // Ensure the caller can receive Ether (EOA or contract with payable fallback)
        // We don't deploy an adversarial helper here because the low-level call is to msg.sender;
        // a fuzzed address is an EOA that always accepts value, which matches the happy path.

        // Fund the caller and deposit into the contract
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        (bool depositOk, ) = address(c).call{value: depositAmount}("");
        require(depositOk, "deposit failed");

        // Perform a number of prior withdrawal calls (which may revert) to advance the state
        for (uint256 i = 0; i < withdrawCallCount; i++) {
            vm.prank(caller);
            // We ignore reverts during these preparatory calls
            try c.withdraw() {} catch {}
        }

        // Perform the final withdrawal call and capture whether it succeeded
        bool finalOk;
        vm.prank(caller);
        try c.withdraw() { finalOk = true; } catch { finalOk = false; }

        // After the final call, check the caller's balance in the contract.
        // The property: if the final call did NOT revert, the caller's balance MUST be zero.
        // In the reference contract, a successful withdraw always zeroes the caller's balance.
        // In the buggy contract, after the first successful withdrawal, the lock remains true,
        // causing the final call to revert and leaving the balance untouched.
        // Therefore, the property "!finalOk || c.balances(caller) == 0" holds for the reference
        // for all inputs, but fails in the buggy version when a zero-amount deposit and a prior
        // successful withdrawal leave a non-zero balance that later cannot be cleared.
        assertTrue(!finalOk || c.balances(caller) == 0, "balance not zero after successful withdraw");
    }
}

