contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 nonZeroAmount, address caller) public {
        // Restrict amounts to avoid overflow in balances addition and to ensure nonZeroAmount is positive
        vm.assume(amount <= type(uint256).max / 2);
        vm.assume(nonZeroAmount > 0 && nonZeroAmount <= type(uint256).max / 2);
        vm.assume(caller != address(0) && caller != address(c) && caller != address(this));

