        (bool depositSuccess,) = address(c).call{value: nonZeroAmount}("");
        require(depositSuccess);

        // Record the non-zero balance before withdraw
        uint256 initialBalance = c.balances(caller);
        // Now perform a withdraw call; it may succeed or fail, we only care about the state after
        vm.prank(caller);
        // The low-level call may fail if the modifier is locked (buggy case after first call);
        // we do not care about the return value, just the resulting state.
        (bool withdrawSuccess,) = address(c).call(abi.encodeWithSignature("withdraw()"));

        // After the call (whether it succeeded or reverted), the caller's balance must be zero
        // because the correct modifier always unlocks after execution; the buggy one locks permanently
        // causing subsequent calls to revert without zeroing the balance.
        assertEq(c.balances(caller), 0);
    }
}

