contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount1, uint256 amount2, address sender, address other) public {
        vm.assume(amount1 > 0 && amount2 > 0);
        vm.assume(sender != address(0) && other != address(0));
        vm.assume(sender != other);

        // Fund the contract via two distinct senders, giving them withdrawable balances
        vm.deal(sender, amount1);
        vm.prank(sender);
        (bool ok1,) = address(c).call{value: amount1}("");
        require(ok1, "fund sender fail");

        vm.deal(other, amount2);
        vm.prank(other);
        (bool ok2,) = address(c).call{value: amount2}("");
        require(ok2, "fund other fail");

        // Withdraw once: first call succeeds, resets sender's balance to 0
        vm.prank(sender);
        try c.withdraw() { } catch { }

        // Withdraw twice: second call for sender will revert on buggy version because lock stays true;
        // on reference it will succeed but balance is already 0, so no effect
        vm.prank(sender);
        try c.withdraw() { } catch { }

        // After both attempts, invariant: sum of all balances == contract ether balance
        uint256 sumBalances = c.balances(sender) + c.balances(other);
        assertEq(sumBalances, address(c).balance, "invariant broken: sum of balances != ether balance");
    }
}

