pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool success,) = address(c).call{value: amount}("");
        require(success);

        FailingCallee failing = new FailingCallee();
        vm.deal(address(failing), 0);
        uint256 balanceBefore = c.balances(address(failing));

        vm.prank(address(failing));
        try c.withdraw() {
            assertTrue(c.balances(address(failing)) == 0);
        } catch {
            assertTrue(c.balances(address(failing)) == balanceBefore);
        }
    }
}

contract FailingCallee {
    fallback() external payable { revert(); }
}
